import React, { useState } from "react";
import { Loader2, MessageSquare, Send } from "lucide-react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
  DialogFooter,
  DialogClose,
} from "@/components/ui/dialog";

import api from "@/api/axios";

const MessageCandidateDialog = ({ application, onMessageSent }) => {
  const [open, setOpen] = useState(false);
  const [sending, setSending] = useState(false);

  const [formData, setFormData] = useState({
    subject: "",
    body: "",
  });

  const candidateName = application?.candidate_name || "Candidate";
  const role = application?.role || "this role";

  const handleChange = (e) => {
    const { name, value } = e.target;

    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const resetForm = () => {
    setFormData({
      subject: "",
      body: "",
    });
  };

  const handleSendMessage = async (e) => {
    e.preventDefault();

    if (!formData.subject.trim()) {
      toast.warning("Subject required", {
        description: "Please enter a message subject.",
      });
      return;
    }

    if (!formData.body.trim()) {
      toast.warning("Message required", {
        description: "Please type your message before sending.",
      });
      return;
    }

    try {
      setSending(true);

      const response = await api.post(
        `/employer/applications/${application.id}/message/`,
        {
          subject: formData.subject,
          body: formData.body,
        },
      );

      toast.success("Message sent", {
        description:
          response.data?.message ||
          `Your message has been sent to ${candidateName}.`,
      });

      resetForm();
      setOpen(false);

      if (onMessageSent) {
        onMessageSent(response.data);
      }
    } catch (error) {
      console.log("Message sending failed:", error.response?.data || error);

      toast.error("Failed to send message", {
        description:
          error.response?.data?.detail ||
          error.response?.data?.body?.[0] ||
          "Please try again.",
      });
    } finally {
      setSending(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button variant="outline" size="sm">
          <MessageSquare className="mr-2 h-4 w-4" />
          Message
        </Button>
      </DialogTrigger>

      <DialogContent className="max-h-[85vh] overflow-y-auto sm:max-w-lg">
        <DialogHeader>
          <DialogTitle>Message Candidate</DialogTitle>
          <DialogDescription>
            Send a direct message to {candidateName} about the application for{" "}
            <strong>{role}</strong>.
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSendMessage} className="mt-4 space-y-5">
          <div className="rounded-lg border bg-slate-50 p-4">
            <p className="text-sm font-medium text-slate-900">
              {candidateName}
            </p>
            <p className="mt-1 text-sm text-muted-foreground">
              {application?.candidate_email}
            </p>
            <p className="mt-1 text-sm text-muted-foreground">Role: {role}</p>
          </div>

          <div className="space-y-2">
            <Label htmlFor="subject">Subject</Label>
            <Input
              id="subject"
              name="subject"
              value={formData.subject}
              onChange={handleChange}
              placeholder="e.g. Interview invitation"
              disabled={sending}
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="body">Message</Label>
            <textarea
              id="body"
              name="body"
              rows="6"
              value={formData.body}
              onChange={handleChange}
              placeholder="Write your message to the candidate..."
              disabled={sending}
              className="w-full rounded-md border bg-background px-3 py-2 text-sm outline-none focus:border-black disabled:cursor-not-allowed disabled:opacity-60"
            />
          </div>

          <DialogFooter>
            <DialogClose asChild>
              <Button type="button" variant="outline" disabled={sending}>
                Cancel
              </Button>
            </DialogClose>

            <Button type="submit" disabled={sending}>
              {sending ? (
                <>
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                  Sending...
                </>
              ) : (
                <>
                  <Send className="mr-2 h-4 w-4" />
                  Send Message
                </>
              )}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
};

export default MessageCandidateDialog;

import React from "react";
import { Link } from "react-router-dom";
import { Building2, Globe, MapPin, Mail, Phone } from "lucide-react";

import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";

const CompanyInfoCard = ({ company }) => {
  if (!company) return null;

  return (
    <Card className="rounded-2xl border border-slate-200 bg-white shadow-sm">
      <CardContent className="p-7">
        <h2 className="text-xl font-extrabold text-slate-950">
          Company Information
        </h2>

        <div className="mt-6 flex items-center gap-4">
          <div className="flex h-16 w-16 items-center justify-center rounded-xl border bg-slate-50">
            {company.logo ? (
              <img
                src={company.logo}
                alt={company.name}
                className="h-10 w-10 object-contain"
              />
            ) : (
              <Building2 className="h-7 w-7 text-slate-500" />
            )}
          </div>

          <div>
            <h3 className="font-bold text-slate-950">{company.name}</h3>
            <p className="text-sm text-slate-500">
              {company.industry || "Company"}
            </p>
          </div>
        </div>

        <p className="mt-5 leading-7 text-slate-600">
          {company.description || "No company description available."}
        </p>

        <div className="mt-6 space-y-4 text-sm text-slate-600">
          <div className="flex items-center gap-3">
            <MapPin className="h-4 w-4 text-yellow-600" />
            <span>{company.location || "Not specified"}</span>
          </div>

          {company.website && (
            <div className="flex items-center gap-3">
              <Globe className="h-4 w-4 text-yellow-600" />
              <a
                href={company.website}
                target="_blank"
                rel="noreferrer"
                className="text-yellow-700 hover:underline"
              >
                {company.website}
              </a>
            </div>
          )}

          {company.contact_email && (
            <div className="flex items-center gap-3">
              <Mail className="h-4 w-4 text-yellow-600" />
              <span>{company.contact_email}</span>
            </div>
          )}

          {company.contact_phone && (
            <div className="flex items-center gap-3">
              <Phone className="h-4 w-4 text-yellow-600" />
              <span>{company.contact_phone}</span>
            </div>
          )}
        </div>

        <Button
          asChild
          className="mt-6 w-full bg-yellow-500 text-black hover:bg-yellow-600"
        >
          <Link to={`/companies/${company.id}`}>View Company Profile</Link>
        </Button>
      </CardContent>
    </Card>
  );
};

export default CompanyInfoCard;

import React from "react";
import { Card, CardContent } from "@/components/ui/card";

const splitText = (text) => {
  if (!text) return [];

  return text
    .split(/\n|•/)
    .map((item) => item.trim())
    .filter(Boolean);
};

const JobDescriptionCard = ({ job }) => {
  return (
    <Card className="rounded-2xl border border-slate-200 bg-white shadow-sm">
      <CardContent className="p-7">
        <h2 className="text-2xl font-extrabold text-slate-950">
          Job Description
        </h2>

        <p className="mt-5 leading-8 text-slate-600">{job.description}</p>

        <div className="mt-8">
          <h3 className="text-xl font-bold text-slate-950">Responsibilities</h3>

          <ul className="mt-4 list-disc space-y-3 pl-6 text-slate-600">
            {splitText(job.responsibilities).map((item, index) => (
              <li key={index} className="leading-7">
                {item}
              </li>
            ))}
          </ul>
        </div>

        <div className="mt-8">
          <h3 className="text-xl font-bold text-slate-950">Requirements</h3>

          <ul className="mt-4 list-disc space-y-3 pl-6 text-slate-600">
            {splitText(job.requirements).map((item, index) => (
              <li key={index} className="leading-7">
                {item}
              </li>
            ))}
          </ul>
        </div>
      </CardContent>
    </Card>
  );
};

export default JobDescriptionCard;

